try:
    print('>>> f = divmod')
    print('>>> x = []')
    print('>>> y = (1, 2)')
    print('>>> f(x, y)')
    f = divmod
    x = []
    y = (1, 2)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
